// TH16 v1.00a Stage 6 MainSub01 (st06.ecl.txt:660-710).
// Four groups of ECir01 enemies spawn at (0,224); each ECir01 drifts outward
// along an accumulating ABS angle and fires one rice bullet backwards per step.
//
// Source motion (st06.ecl.txt:164-174):
//   moveVel(F2, 0)            -> ABS angle F2, speed 0
//   moveSpeedTime(60, 1, 1)   -> speed 0->1 with mode1 (t^2)
//   moveAngleTime(600, 7, F3) -> angle += F3 for 600 updates (mode7)
//   clock 120: moveSpeedTime(120, 1, 2) -> speed 1->2 with t^2
// The target integrates after ECL, so arm the next source step each frame.

const TIME_LIMIT: int = 2560;
const OPENING_BUFFER: int = 120;

const TH16_RICE: int = 480;

// Source ECir01_at (st06.ecl.txt:183-232): one 1x1 emit every gap frames,
// angle = ABS_ANGLE + pi + RANDF2*spread. ANIM a=1 keeps spawn retreat 4*v.
async sub ecir_fire(b_count: int, gap: int, speed: fx, spread: int) {
    wait(10);
    for n in 0..b_count {
        var ra: int = rand(65536);
        var u: fx = (ra - 32768) as fx / 32768;
        var off: int = (spread as fx * u) as int;
        var a: angle = (self_int(0) + 32768 + off) as angle;
        _ = fire(TH16_RICE, 6,
                 $self_x - 4fx * speed * cos(a),
                 $self_y - 4fx * speed * sin(a),
                 speed, a, none, none);
        wait(gap);
    }
}

// Mode1 (t^2) speed ramp and mode7 (per-update delta) angle accumulation.
sub arm_step(base: int, delta: int, k: int) {
    var th: int = base + delta * k;
    if k > 600 { th = base + delta * 600; }
    var s: fx = 2fx;
    if k <= 60 {
        var t: fx = (k as fx) / 60fx;
        s = t * t;
    } else if k <= 120 {
        s = 1fx;
    } else if k <= 240 {
        var u: fx = ((k - 120) as fx) / 120fx;
        s = 1fx + u * u;
    }
    var a: angle = th as angle;
    move_vel_xy(0, s * cos(a), s * sin(a), EASE_LINEAR);
}

async sub ecir_child(base: int, delta: int, b_count: int, gap: int, speed: fx, spread: int) {
    set_invuln(65535);
    set_hitbox(8fx);   // source setHitbox(16,16): first value * 0.5
    set_hurtbox(12fx); // source setHurtbox(24,24): first value * 0.5
    set_self_int(0, base);
    arm_step(base, delta, 1);
    var k: int = 0;
    loop {
        wait(1);
        k = k + 1;
        var th: int = base + delta * k;
        if k > 600 { th = base + delta * 600; }
        set_self_int(0, th);
        // st06.ecl.txt:172 @ECir01_at() async
        if k == 60 { spawn ecir_fire(b_count, gap, speed, spread); }
        arm_step(base, delta, k + 1);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wait(120); // st06.ecl.txt:663

    // st06.ecl.txt:192-227: bullet speed and random spread per difficulty.
    var rank: int = global(GVAR_RANK);
    var b_count: int = 40;
    var gap: int = 40;
    var speed: fx = 1fx;
    var spread: int = 182;    // 1 degree
    if rank == 1 {
        b_count = 200; gap = 10; speed = 1fx; spread = 5461;
    } else if rank == 2 {
        b_count = 300; gap = 8; speed = 1.5fx; spread = 5461;
    } else if rank == 3 {
        b_count = 400; gap = 5; speed = 2.5fx; spread = 5461; // 30 degrees
    }

    var base: int = 0;
    // st06.ecl.txt:670-675: 10 spawns, F2 starts 0 and steps -20deg, F3=+1deg/frame.
    for i1 in 0..10 {
        _ = spawn_enemy(0fx, 224fx, 350, 0, 1000, 0,
                        ecir_child(base, 182, b_count, gap, speed, spread));
        base = base - 3641;
        wait(2);
    }
    wait(230); // st06.ecl.txt:676
    // st06.ecl.txt:680-686: 10 spawns, F2 starts 0 and steps +20deg, F3=-1deg/frame.
    base = 0;
    for i2 in 0..10 {
        _ = spawn_enemy(0fx, 224fx, 350, 0, 1000, 0,
                        ecir_child(base, -182, b_count, gap, speed, spread));
        base = base + 3641;
        wait(2);
    }
    wait(230); // st06.ecl.txt:687
    // st06.ecl.txt:691-697: 20 spawns, F2 starts 0 and steps +222.5deg, F3=+2deg/frame.
    base = 0;
    for i3 in 0..20 {
        _ = spawn_enemy(0fx, 224fx, 350, 0, 1000, 0,
                        ecir_child(base, 364, b_count, gap, speed, spread));
        base = base + 40505;
        wait(2);
    }
    wait(270); // st06.ecl.txt:698
    // st06.ecl.txt:702-708: 20 spawns, F2 starts 0 and steps -222.5deg, F3=-2deg/frame.
    base = 0;
    for i4 in 0..20 {
        _ = spawn_enemy(0fx, 224fx, 350, 0, 1000, 0,
                        ecir_child(base, -364, b_count, gap, speed, spread));
        base = base - 40505;
        wait(2);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
